 function update(){if(typeof StudioTimeline!=='undefined')StudioTimeline.update();if($('#s-position'))$('#s-position').textContent=format(time)+' / '+format(length());if($('#s-seek'))$('#s-seek').value=time;if($('#video-play'))$('#video-play').innerHTML=state.playing?'Ⅱ':icon('play');if($('#s-play-label'))$('#s-play-label').textContent=state.playing?'Pause':'Play';}
 const nativePreviewSources=new Set();
